(async () => {
  const organizationID = {{global:firstLvDeptId}};

  const resBatchConfig = await db
    .collection("batch_number_config")
    .where({ organization_id: organizationID })
    .get();

  if (resBatchConfig.data.length > 0) {
    this.toView({
      target: "2058765580973846530",
      targetType: "Table",
      mode: "dialog",
      type: "edit",
      data: {
        id: resBatchConfig.data[0].id
      },
      defaultValue: {trigger_from: "Organization"},
      title: "Batch Number Config",
    });
    return;
  } else {
    this.toView({
      target: "2058765580973846530",
      targetType: "Table",
      mode: "dialog",
      type: "add",
      data: { trigger_from: "Organization" },
      title: "Batch Number Config",
    });
  }
})();

